main() {
    // Decimal literals
    let decimal = 42
    println("Decimal 42 = ${decimal}")

    // Different numeral systems for the same value
    let hex = 0x2A        // Hexadecimal
    let binary = 0b101010  // Binary
    println("Hexadecimal 0x2A = ${hex}")
    println("Binary 0b101010 = ${binary}")

    // Using underscores for readability
    let million = 1_000_000
    println("One million = ${million}")

    // Using suffixes to specify types
    let small: Int8 = 127
    let unsigned: UInt64 = 100u64
    println("Int8: ${small}, UInt64: ${unsigned}")

    // Verify that Int64 is the default type
    let inferred = 999
    println("Inferred type: ${inferred}")
}

main() {
    // Basic floating-point operations
    let distance = 5.5       // Default Float64
    let time = 2.0
    let speed = distance / time
    println("Distance: ${distance} km")
    println("Time: ${time} h")
    println("Average speed: ${speed} km/h")

    // Scientific notation
    let scientific = 2.4e-1  // 0.24
    println("Scientific notation 2.4e-1 = ${scientific}")

    // Using suffixes to specify types
    let pi: Float32 = 3.14159f32
    let e = 2.718f64
    println("π ≈ ${pi}")
    println("e ≈ ${e}")

    // Hexadecimal floating-point literal
    let hexFloat = 0x1.1p0   // 1.0625
    println("Hexadecimal float 0x1.1p0 = ${hexFloat}")

    // Floating-point operations
    let avg = (72.5 + 81.0) / 2.0
    println("Average score: ${avg}")
}

main() {
    // Boolean literals
    let isActive = true
    let isAdmin = false
    println("Active user: ${isActive}")
    println("Admin: ${isAdmin}")

    // Logical NOT operation
    println("NOT true = ${!isActive}")
    println("NOT false = ${!isAdmin}")

    // Logical AND and OR
    println("true && false = ${isActive && isAdmin}")
    println("true || false = ${isActive || isAdmin}")

    // Short-circuit evaluation demonstration
    func getValue(): Bool {
        println("  getValue() was called")
        true
    }
    
    println("Short-circuit evaluation example:")
    let r1 = false && getValue()  // getValue will not be called
    println("After false && getValue(), getValue was not called")
    
    let r2 = true || getValue()   // getValue will not be called
    println("After true || getValue(), getValue was not called")

    // Comparison operators produce boolean values
    let x = 10
    let y = 20
    println("${x} > ${y}: ${x > y}")
    println("${x} < ${y}: ${x < y}")
    println("${x} == ${y}: ${x == y}")
    println("${x} != ${y}: ${x != y}")
}

main() {
    // Unit type: println returns Unit
    let result: Unit = println("println's return value is Unit")
    println("Unit value: ${result}")
    
    // Unit's only value is ()
    let empty: Unit = ()
    println("Empty value: ${empty}")
    
    // Assignment expression type is also Unit
    var x = 10
    let assignResult = (x = 20)
    println("After assignment x = ${x}")
    println("Assignment expression result: ${assignResult}")

    // Nothing type for control flow
    // break, continue, return have type Nothing
    println("Starting loop")
    for (i in 0..5) {
        if (i == 3) {
            println("Encountered i=3, executing break")
            break  // break's type is Nothing
            // Code after break will not execute
            println("This line will not print")
        }
        println("i = ${i}")
    }
    println("Loop ended")

    // Nothing is a subtype of all types, enabling flexible type inference
    func assertPositive(n: Int64): Unit {
        if (n < 0) {
            throw IllegalArgumentException("n must be positive")
            // throw's type is Nothing, so function returns Unit
        }
        println("${n} is positive")
    }
    
    assertPositive(42)
}

