main() {
    let day = 3

    // match returns a value, assigned to variable
    let name = match (day) {
        case 1 => "Monday"
        case 2 => "Tuesday"
        case 3 => "Wednesday"
        case 4 => "Thursday"
        case 5 => "Friday"
        case 6 => "Saturday"
        case 7 => "Sunday"
        case _ => "Invalid date"
    }
    println("Today is ${name}")

    // match can also be used as a statement without returning a value
    match (day) {
        case 1 | 2 | 3 | 4 | 5 => println("Weekday")
        case 6 | 7 => println("Weekend")
        case _ => println("Invalid")
    }
}

main() {
    let grade = "B"

    // Match string literals
    match (grade) {
        case "A" => println("Excellent")
        case "B" => println("Good")
        case "C" => println("Pass")
        case _ => println("Other grade")
    }

    // Use | to match multiple values
    let month = 8
    let season = match (month) {
        case 3 | 4 | 5 => "Spring"
        case 6 | 7 | 8 => "Summer"
        case 9 | 10 | 11 => "Autumn"
        case 12 | 1 | 2 => "Winter"
        case _ => "Invalid month"
    }
    println("Month ${month} is ${season}")

    // Multi-value matching can also be used for booleans and other types
    let isWeekend = true
    match (isWeekend) {
        case true => println("Time to rest!")
        case false => println("Keep working hard")
    }
}

main() {
    let code = 404

    // Binding pattern: capture the matched value
    match (code) {
        case 200 => println("Request successful")
        case 301 => println("Permanent redirect")
        case 404 => println("Resource not found")
        case other => println("Received status code: ${other}")  // Binds any other value
    }

    // Binding pattern can return results using the value
    let score = 75
    let result = match (score) {
        case 100 => "Perfect score!"
        case 0 => "Zero score"
        case n => "Score: ${n}"  // Use the bound value
    }
    println(result)

    // Binding pattern is useful for handling remaining cases
    let count = 3
    match (count) {
        case 0 => println("No items")
        case 1 => println("One item")
        case n => println("${n} items")  // Bind and display
    }
}

main() {
    let point = (1, 0)

    // Tuple pattern: match and destructure coordinates
    match (point) {
        case (0, 0) => println("This is the origin")
        case (x, 0) => println("On x-axis, x = ${x}")
        case (0, y) => println("On y-axis, y = ${y}")
        case (x, y) => println("Coordinate point (${x}, ${y})")
    }

    // Combining value patterns and binding patterns
    let record = ("Alice", 95)
    match (record) {
        case (name, 100) => println("${name} got a perfect score!")
        case (name, score) => println("${name}'s score: ${score}")
    }

    // Triple tuple matching
    let rgb = (255, 128, 0)
    match (rgb) {
        case (255, 255, 255) => println("White")
        case (0, 0, 0) => println("Black")
        case (r, g, b) => println("RGB(${r}, ${g}, ${b})")
    }
}

interface Shape {
    func area(): Int64
}

open class Circle <: Shape {
    let radius: Int64

    init(radius: Int64) {
        this.radius = radius
    }

    public func area(): Int64 {
        radius * radius * 3  // Simplified calculation
    }
}

class Rectangle <: Shape {
    let width: Int64
    let height: Int64

    init(width: Int64, height: Int64) {
        this.width = width
        this.height = height
    }

    public func area(): Int64 {
        width * height
    }
}

func describe(shape: Shape): String {
    match (shape) {
        case c: Circle =>
            "Circle, radius ${c.radius}, area ${c.area()}"
        case r: Rectangle =>
            "Rectangle, width ${r.width} height ${r.height}, area ${r.area()}"
        case _ =>
            "Unknown shape"
    }
}

main() {
    let shapes: Array<Shape> = [Circle(5), Rectangle(3, 4)]
    for (shape in shapes) {
        println(describe(shape))
    }
}

main() {
    let number = 15

    // Pattern guard: add condition check after matching
    match (number) {
        case n where n < 0 => println("${n} is negative")
        case n where n == 0 => println("Zero")
        case n where n % 2 == 0 => println("${n} is positive even")
        case n => println("${n} is positive odd")
    }

    // Practical application: grade evaluation
    let score = 82
    let grade = match (score) {
        case s where s >= 90 => "A (Excellent)"
        case s where s >= 80 => "B (Good)"
        case s where s >= 70 => "C (Average)"
        case s where s >= 60 => "D (Pass)"
        case _ => "F (Fail)"
    }
    println("Score ${score} => ${grade}")

    // Using guards with value patterns
    let temp = 25
