main() {
    let point = (1, 0)

    // Tuple pattern: match and destructure coordinates
    match (point) {
        case (0, 0) => println("This is the origin")
        case (x, 0) => println("On x-axis, x = ${x}")
        case (0, y) => println("On y-axis, y = ${y}")
        case (x, y) => println("Coordinate point (${x}, ${y})")
    }

    // Combining value patterns and binding patterns
    let record = ("Alice", 95)
    match (record) {
        case (name, 100) => println("${name} got a perfect score!")
        case (name, score) => println("${name}'s score: ${score}")
    }

    // Triple tuple matching
    let rgb = (255, 128, 0)
    match (rgb) {
        case (255, 255, 255) => println("White")
        case (0, 0, 0) => println("Black")
        case (r, g, b) => println("RGB(${r}, ${g}, ${b})")
    }
}

interface Shape {
    func area(): Int64
}

open class Circle <: Shape {
    let radius: Int64

    init(radius: Int64) {
        this.radius = radius
    }

    public func area(): Int64 {
        radius * radius * 3  // Simplified calculation
    }
}

class Rectangle <: Shape {
    let width: Int64
    let height: Int64

    init(width: Int64, height: Int64) {
        this.width = width
        this.height = height
    }

    public func area(): Int64 {
        width * height
    }
}

func describe(shape: Shape): String {
    match (shape) {
        case c: Circle =>
            "Circle, radius ${c.radius}, area ${c.area()}"
        case r: Rectangle =>
            "Rectangle, width ${r.width} height ${r.height}, area ${r.area()}"
        case _ =>
            "Unknown shape"
    }
}

main() {
    let shapes: Array<Shape> = [Circle(5), Rectangle(3, 4)]
    for (shape in shapes) {
        println(describe(shape))
    }
}

