    return 0
}

import std.collection.ArrayList

main(): Int64 {
    let numbers = ArrayList<Int64>([1, 2, 3, 4, 5])
    println("Original list: ${numbers}")
    
    // Map: square each element
    let squares = ArrayList<Int64>()
    for (number in numbers) {
        squares.add(number * number)
    }
    println("\nAfter map (square): ${squares}")
    
    // Filter: keep only even numbers
    let evens = ArrayList<Int64>()
    for (number in numbers) {
        if (number % 2 == 0) {
            evens.add(number)
        }
    }
    println("After filter (even numbers): ${evens}")
    
    // Reduce: sum all elements
    var sum: Int64 = 0
    for (number in numbers) {
        sum += number
    }
    println("After reduce (sum): ${sum}")
    
    // Combination example: filter then map
    let evenSquares = ArrayList<Int64>()
    for (number in numbers) {
        if (number % 2 == 0) {
            evenSquares.add(number * number)
        }
    }
    println("\nFilter even numbers, then square: ${evenSquares}")
    
    // Combination example: map then filter
    let squaresOver5 = ArrayList<Int64>()
    for (number in numbers) {
        let sq = number * number
        if (sq > 5) {
            squaresOver5.add(sq)
        }
    }
    println("Square first, then filter > 5: ${squaresOver5}")
    
    return 0
}

import std.collection.{ArrayList, HashMap, HashSet}

main(): Int64 {
    // Array -> ArrayList
    let rawIds = [101, 102, 102, 103, 103, 104]
    let idList = ArrayList<Int64>(rawIds)
    println("Original array: ${rawIds}")
    println("ArrayList size: ${idList.size}")
    
    // ArrayList -> HashSet (deduplication)
    let uniqueIds = HashSet<Int64>(idList)
    println("HashSet size (after deduplication): ${uniqueIds.size}")
    print("Unique IDs:")
    for (id in uniqueIds) {
        print(" ${id}")
    }
    println()
    
    // Tuple array -> HashMap
    let pairs = [("alice", 95), ("bob", 88), ("carol", 92)]
    let scores = HashMap<String, Int64>(pairs)
    println("\nHashMap size: ${scores.size}")
    println("Student score table:")
    for ((name, score) in scores) {
        println("  ${name} => ${score}")
    }
    
    // HashSet -> ArrayList (ordering)
    let sortedIds = ArrayList<Int64>(uniqueIds)
    println("\nHashSet -> ArrayList:")
    println("  size = ${sortedIds.size}")
    
    // HashMap -> ArrayList (extract keys or values)
    let names = ArrayList<String>()
    for ((name, _) in scores) {
        names.add(name)
    }
    println("Extract all keys:")
    for (name in names) {
        print(" ${name}")
    }
    println()
    
    return 0
}

import std.collection.ArrayList

func sortAscending(values: ArrayList<Int64>): Unit {
    var i = 0
    while (i < values.size) {
        // Find the index of the minimum value among remaining elements
        var minIndex = i
        var j = i + 1
        while (j < values.size) {
            if (values[j] < values[minIndex]) {
                minIndex = j
            }
            j += 1
        }
        
        // Swap current position with minimum value position
        if (minIndex != i) {
            let temp = values[i]
            values[i] = values[minIndex]
            values[minIndex] = temp
        }
        
        i += 1
    }
}

main(): Int64 {
    let scores = ArrayList<Int64>([42, 7, 19, 88, 7, 23, 56])
    
    println("Before sorting:")
    for (score in scores) {
        print("${score} ")
    }
    println()
    
    // Sort
    sortAscending(scores)
    
    println("After sorting (ascending):")
    for (score in scores) {
        print("${score} ")
    }
    println()
    
    return 0
}

