// Readable interface
interface Readable {
    func read(): String
}

// Writable interface
interface Writable {
    func write(data: String): Unit
}

// Composite interface: supports both reading and writing
interface ReadWrite <: Readable & Writable {
    // Can add new methods
    func clear(): Unit {
        // Provide default implementation
        println("Content cleared")
    }
}

// File buffer implements ReadWrite
class FileBuffer <: ReadWrite {
    var content: String = ""

    public func read(): String {
        if (content.isEmpty()) {
            "<empty>"
        } else {
            content
        }
    }

    public func write(data: String): Unit {
        content = data
    }

    public func clear(): Unit {
        content = ""
        println("Buffer cleared")
    }
}

// Network stream implements ReadWrite
class NetworkStream <: ReadWrite {
    var buffer: String = ""

    public func read(): String {
        buffer
    }

    public func write(data: String): Unit {
        buffer = data
        println("Data sent: ${data}")
    }
}

// Function to handle readable objects
func showContent(r: Readable) {
    println("Content: ${r.read()}")
}

// Function to handle writable objects
func writeData(w: Writable, data: String) {
    w.write(data)
}

main() {
    let buffer = FileBuffer()

    // Use as ReadWrite
    println("=== As ReadWrite ===")
    buffer.write("Hello, Cangjie!")
    println("Read: ${buffer.read()}")
    buffer.clear()

    // Can assign to parent interface types
    println("\n=== Subtype Conversion ===")
    let reader: Readable = buffer  // ReadWrite -> Readable
    let writer: Writable = buffer  // ReadWrite -> Writable

    writer.write("Interface inheritance example")
    showContent(reader)  // Use Readable interface

    // Multiple ReadWrite objects
    println("\n=== Heterogeneous Collection ===")
    let streams: Array<ReadWrite> = [
        FileBuffer(),
        NetworkStream()
    ]

    for (s in streams) {
        s.write("Test data")
        println("Read: ${s.read()}")
        println()
    }
}

// Animal base class
open class Animal {
    public open func speak(): String {
        "Animal sound"
    }
}

// Dog class
class Dog <: Animal {
    public override func speak(): String {
        "Woof woof!"
    }

    public func fetch(): String {
        "The dog fetched the ball"
    }
}

// Cat class
class Cat <: Animal {
    public override func speak(): String {
        "Meow meow~"
    }

    public func climb(): String {
        "The cat climbed the tree"
    }
}

// Function to handle animals
func handleAnimal(a: Animal) {
    println("Animal speaks: ${a.speak()}")

    // Use is to check runtime type
    println("Is dog? ${a is Dog}")
    println("Is cat? ${a is Cat}")

    // Use as for safe conversion and access to type-specific methods
    match (a as Dog) {
        case Some(dog) => 
            println("Dog-specific action: ${dog.fetch()}")
        case None => ()
    }

    match (a as Cat) {
        case Some(cat) =>
            println("Cat-specific action: ${cat.climb()}")
        case None => ()
    }
}

// Process animals in batch
func processAnimals(animals: Array<Animal>) {
    var dogCount = 0
    var catCount = 0

    for (a in animals) {
        if (a is Dog) {
            dogCount++
        } else if (a is Cat) {
            catCount++
        }
    }

    println("Statistics: ${dogCount} dogs, ${catCount} cats")
}

