// Define enum with data: different shapes carry different parameters
enum Shape {
    | Circle(Float64)              // Circle: radius
    | Rectangle(Float64, Float64)  // Rectangle: width and height
    | Triangle(Float64, Float64)   // Triangle: base and height
}

// Calculate the area of a shape
func area(s: Shape): Float64 {
    match (s) {
        case Circle(r) => 
            3.14159 * r * r
        case Rectangle(w, h) => 
            w * h
        case Triangle(b, h) => 
            0.5 * b * h
    }
}

// Generate a description string for a shape
func describe(s: Shape): String {
    match (s) {
        case Circle(r) => 
            "Circle(radius=${r})"
        case Rectangle(w, h) => 
            "Rectangle(${w} x ${h})"
        case Triangle(b, h) => 
            "Triangle(base=${b}, height=${h})"
    }
}

main() {
    // Create instances of different shapes
    let shapes = [
        Shape.Circle(5.0),
        Shape.Rectangle(4.0, 6.0),
        Shape.Triangle(3.0, 8.0)
    ]

    // Iterate and output information for each shape
    for (s in shapes) {
        let desc = describe(s)
        let a = area(s)
        println("${desc}, area = ${a}")
    }
}

// Recursive enum: representing arithmetic expressions
enum Expr {
    | Num(Int64)          // Number
    | Add(Expr, Expr)     // Addition: two sub-expressions
    | Mul(Expr, Expr)     // Multiplication: two sub-expressions
}

// Recursively calculate the value of an expression
func eval(e: Expr): Int64 {
    match (e) {
        case Num(n) => 
            n
        case Add(left, right) => 
            eval(left) + eval(right)
        case Mul(left, right) => 
            eval(left) * eval(right)
    }
}

// Convert an expression to string representation
func show(e: Expr): String {
    match (e) {
        case Num(n) => 
            "${n}"
        case Add(l, r) => 
            "(${show(l)} + ${show(r)})"
        case Mul(l, r) => 
            "(${show(l)} * ${show(r)})"
    }
}

main() {
    // Construct expression: (2 + 3) * 4
    let expr1 = Expr.Mul(
        Expr.Add(Expr.Num(2), Expr.Num(3)),
        Expr.Num(4)
    )
    println("${show(expr1)} = ${eval(expr1)}")

    // Construct expression: 1 + (2 * 3)
    let expr2 = Expr.Add(
        Expr.Num(1),
        Expr.Mul(Expr.Num(2), Expr.Num(3))
    )
    println("${show(expr2)} = ${eval(expr2)}")

    // Construct expression: (10 + 20) * (3 + 4)
    let expr3 = Expr.Mul(
        Expr.Add(Expr.Num(10), Expr.Num(20)),
        Expr.Add(Expr.Num(3), Expr.Num(4))
    )
    println("${show(expr3)} = ${eval(expr3)}")
}

// Find the index of a target value in an array
func findIndex(arr: Array<Int64>, target: Int64): Option<Int64> {
    for (i in 0..arr.size) {
        if (arr[i] == target) {
            return Some(i)  // Found, return index
        }
    }
    None  // Not found
}

