// Calculate the sum of all integers in the [start, end] range
func sumRange(start: Int64, end: Int64): Int64 {
    var total: Int64 = 0
    var current = start
    while (current <= end) {
        total += current
        current += 1
    }
    return total
}

main() {
    println("Calculating sum from 1 to 100...")

    // Calculate the first half in a new thread
    let left = spawn {
        sumRange(1, 50)
    }

    // Calculate the second half in another new thread
    let right = spawn {
        sumRange(51, 100)
    }

    // Wait for both threads to finish and get results
    let leftSum = left.get()
    let rightSum = right.get()
    let total = leftSum + rightSum

    println("Left half (1-50): ${leftSum}")
    println("Right half (51-100): ${rightSum}")
    println("Total: ${total}")
}

import std.sync.SyncCounter

main() {
    // Create a counter as a "gate" with initial value 1
    let gate = SyncCounter(1)

    // Create a worker thread
    let worker = spawn {
        println("worker: waiting for gate to open")
        gate.waitUntilZero()  // Block until counter reaches zero

        // Check if there's a cancellation request
        if (Thread.currentThread.hasPendingCancellation) {
            println("worker: received cancellation request, exiting early")
            return
        }

        println("worker: continuing with task")
    }

    // First send the cancellation request
    println("Main thread: sending cancellation request")
    worker.cancel()

    // Then open the gate (decrement counter by 1)
    println("Main thread: opening gate")
    gate.dec()

    // Wait for worker thread to finish
    worker.get()
    println("Main thread: done")
}

main() {
    println("Countdown starting...")

    var count = 5
    while (count > 0) {
        println("${count}...")
        
        // Pause for 200 milliseconds
        sleep(200 * Duration.millisecond)
        
        count -= 1
    }

    // Pause briefly before printing "go"
    sleep(300 * Duration.millisecond)
    println("go!")
    
    println("Countdown finished")
}

